package com.bakaroo.bingo.backend.feature.wallet.service;

import com.bakaroo.bingo.backend.common.exception.*;
import com.bakaroo.bingo.backend.common.idempotency.*;
import com.bakaroo.bingo.backend.common.money.MoneyValues;
import com.bakaroo.bingo.backend.common.request.RequestHashService;
import com.bakaroo.bingo.backend.feature.auth.service.BingoUserPrincipal;
import com.bakaroo.bingo.backend.feature.user.entity.*;
import com.bakaroo.bingo.backend.feature.wallet.config.WalletProperties;
import com.bakaroo.bingo.backend.feature.wallet.dto.*;
import com.bakaroo.bingo.backend.feature.wallet.entity.*;
import com.bakaroo.bingo.backend.feature.wallet.repository.*;
import java.math.BigDecimal; import java.time.Instant; import java.util.Locale; import java.util.UUID;
import org.springframework.data.domain.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;

@Service
public class WithdrawalService {
 private final WithdrawalRequestRepository requests; private final WalletRepository wallets; private final WalletTransactionRepository transactions; private final WalletProperties properties; private final IdempotencyService idempotency; private final RequestHashService hashes;
 public WithdrawalService(WithdrawalRequestRepository requests,WalletRepository wallets,WalletTransactionRepository transactions,WalletProperties properties,IdempotencyService idempotency,RequestHashService hashes){this.requests=requests;this.wallets=wallets;this.transactions=transactions;this.properties=properties;this.idempotency=idempotency;this.hashes=hashes;}
 @Transactional(readOnly=true) public Page<WithdrawalResponse> own(BingoUserPrincipal p,Pageable page){return requests.findByPlayerIdOrderByCreatedAtDescIdDesc(p.getUser().getId(),page).map(WithdrawalResponse::from);}
 @Transactional(readOnly=true) public Page<WithdrawalResponse> search(String query,WithdrawalStatus status,Pageable page){String q=query==null||query.isBlank()?null:query.trim().toLowerCase(Locale.ROOT);Long id=null;if(q!=null){try{id=Long.valueOf(q);}catch(NumberFormatException ignored){}}return requests.search(q,id,status,page).map(WithdrawalResponse::from);}
 @Transactional public IdempotentResult<WithdrawalResponse> submit(BingoUserPrincipal p,WithdrawalRequestDto dto,String key){User player=p.getUser();if(!player.hasRole(UserRole.PLAYER))throw new BadRequestException("PLAYER_ROLE_REQUIRED","Player account required");if(!properties.currency().equalsIgnoreCase(dto.currency()))throw new BadRequestException("UNSUPPORTED_CURRENCY","Unsupported currency");String type=dto.destinationType().toUpperCase(Locale.ROOT);if(type.equals("TELEBIRR")&&(dto.phoneNumber()==null||dto.phoneNumber().isBlank()))throw new BadRequestException("PHONE_REQUIRED","Telebirr phone number is required");if(type.equals("BANK")&&(dto.bankName()==null||dto.bankName().isBlank()||dto.accountNumber()==null||dto.accountNumber().isBlank()))throw new BadRequestException("BANK_DETAILS_REQUIRED","Bank name and account number are required");BigDecimal amount=MoneyValues.money(dto.amount());String hash=hashes.hash("POST","/api/v1/wallet/withdrawals",dto),op=UUID.randomUUID().toString();return idempotency.execute(player.getId(),key,hash,op,HttpStatus.CREATED.value(),WithdrawalResponse.class,()->{Wallet w=wallets.findByOwnerIdForUpdate(player.getId()).orElseThrow(()->new NotFoundException("WALLET_NOT_FOUND","Wallet not found"));BigDecimal before=w.getAvailableBalance();if(before.compareTo(amount)<0)throw new ConflictException("INSUFFICIENT_BALANCE","Available wallet balance is insufficient");BigDecimal after=MoneyValues.money(before.subtract(amount));w.setAvailableBalance(after);WithdrawalRequest r=requests.save(WithdrawalRequest.create(player,op,amount,w.getCurrency(),type,dto.accountName().trim(),blank(dto.phoneNumber()),blank(dto.bankName()),blank(dto.accountNumber()),Instant.now()));transactions.save(WalletTransaction.create(w,op,WalletTransactionType.WALLET_WITHDRAWAL_DEBIT,amount,before,after,w.getPromotionalBalance(),w.getPromotionalBalance(),w.getCurrency(),"WALLET_WITHDRAWAL",r.getId(),"Withdrawal request submitted",null,Instant.now()));return WithdrawalResponse.from(r);});}
 @Transactional public IdempotentResult<WithdrawalResponse> complete(Long id,BingoUserPrincipal p,WithdrawalReviewDto dto,String key){User staff=requireStaff(p);if(dto.transferReference()==null||dto.transferReference().isBlank())throw new BadRequestException("TRANSFER_REFERENCE_REQUIRED","Transfer reference is required");return review(id,staff,dto,key,true);}
 @Transactional public IdempotentResult<WithdrawalResponse> reject(Long id,BingoUserPrincipal p,WithdrawalReviewDto dto,String key){User staff=requireStaff(p);return review(id,staff,dto,key,false);}
 private IdempotentResult<WithdrawalResponse> review(Long id,User staff,WithdrawalReviewDto dto,String key,boolean complete){String path="/api/v1/admin/wallet/withdrawals/"+id+(complete?"/complete":"/reject");String hash=hashes.hash("POST",path,dto),op=UUID.randomUUID().toString();return idempotency.execute(staff.getId(),key,hash,op,200,WithdrawalResponse.class,()->{WithdrawalRequest r=requests.findByIdForUpdate(id).orElseThrow(()->new NotFoundException("WITHDRAWAL_NOT_FOUND","Withdrawal not found"));if(r.getStatus()!=WithdrawalStatus.PENDING)throw new ConflictException("WITHDRAWAL_ALREADY_REVIEWED","Withdrawal is already reviewed");Instant now=Instant.now();if(complete)r.complete(staff,dto.transferReference().trim(),dto.reviewNote().trim(),now);else{r.reject(staff,dto.reviewNote().trim(),now);Wallet w=wallets.findByOwnerIdForUpdate(r.getPlayer().getId()).orElseThrow();BigDecimal before=w.getAvailableBalance(),after=MoneyValues.money(before.add(r.getAmount()));w.setAvailableBalance(after);transactions.save(WalletTransaction.create(w,op,WalletTransactionType.WALLET_WITHDRAWAL_REFUND,r.getAmount(),before,after,w.getPromotionalBalance(),w.getPromotionalBalance(),w.getCurrency(),"WALLET_WITHDRAWAL",r.getId(),dto.reviewNote().trim(),null,now));}return WithdrawalResponse.from(requests.save(r));});}
 private User requireStaff(BingoUserPrincipal p){User u=p.getUser();if(!u.isActive()||!(u.hasRole(UserRole.ADMIN)||u.hasRole(UserRole.SUPPORT)))throw new BadRequestException("STAFF_ROLE_REQUIRED","Active admin or support account required");return u;}
 private String blank(String v){return v==null||v.isBlank()?null:v.trim();}
}
